<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/Web/View.php';
require_once __DIR__.'/mysql-bootstrap.php';
use Kulturhus\Verein\{Database,Finance,FinanceWorkflowActions,Settings};
use Kulturhus\Verein\Tests\MySqlFixture;
set_error_handler(static function($s,$m,$f,$l){throw new ErrorException($m,0,$s,$f,$l);});
$db=MySqlFixture::connect();Database::migrate($db);$n=0;
function check(bool $v,string $s):void{global $n;if(!$v)throw new RuntimeException($s);++$n;echo "PASS $s\n";}
function denied(callable $fn,string $s):void{try{$fn();}catch(DomainException){check(true,$s);return;}throw new RuntimeException($s);}
$db->exec("INSERT INTO clubs VALUES('a','Synthetic A'),('b','Synthetic B');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','member',1),('writer','a','treasurer',0),('reader','a','member',0),('foreign','b','treasurer',0)");
$settings=new Settings($db,'admin');$role=$settings->saveRole('',0,['name'=>'Read only','finance_access'=>'read','members_access'=>'none']);$settings->assignRole('reader',$role,0);
$f=new Finance($db,'writer');$id=$f->createAccount('Synthetic Bank','offline','4496,34','2026-01-01');$other=$f->createAccount('Other account','offline','0','2026-01-01');
$before=$f->account($id);$result=FinanceWorkflowActions::handle($db,'writer',['action'=>'finance-account-settings','account'=>$id,'version'=>'0','name'=>'Renamed Bank','active'=>'1','tax_account'=>'18000','fints_read'=>'1','fints_write'=>'0']);
check($f->account($id)===array_replace($before,['name'=>'Renamed Bank']),'rename keeps identity, balance, type and date');
check($result['route']['edit_account']===1&&$result['route']['account']===$id,'save stays on same account editor');
check((int)$f->accounts()[1]['balance_cents']===449634,'rename never imports or fabricates bank balance');
check((int)$db->query("SELECT COUNT(*) FROM audit_events WHERE action='finance.account.renamed'")->fetchColumn()===1,'rename audited');
$snapshot=MySqlFixture::snapshot($db);
denied(fn()=>$f->saveAccountSettings($id,0,true,'',true,false,'stale'),'stale name form rejected');
denied(fn()=>$f->saveAccountSettings($id,1,true,'',true,false,'Other account'),'duplicate name rejected');
denied(fn()=>$f->saveAccountSettings($id,1,true,'',true,false,"bad\nname"),'control characters rejected');
denied(fn()=>$f->saveAccountSettings($id,1,true,'99999',true,false,'No partial rename'),'invalid bookkeeping account rolls name back');
foreach(['reader','foreign'] as $actor)denied(fn()=>(new Finance($db,$actor))->saveAccountSettings($id,1,true,'',true,false,'Forbidden'),'role and tenant '.$actor);
denied(fn()=>$f->saveAccountSettings($id,1,true,'',true,false,null,'cash','1.000,00'),'ambiguous opening rejected');
denied(fn()=>$f->saveAccountSettings($id,1,true,'',true,false,null,'cash','0','2099-01-01'),'future opening rejected');
check(MySqlFixture::snapshot($db)===$snapshot,'failed edits leave all rows untouched');
$f->saveAccountSettings($id,1,true,'',true,false,'Renamed Cash','cash','12,34','2026-02-01');
check($f->account($id)['kind']==='cash'&&(int)$f->account($id)['opening_cents']===1234&&$f->account($id)['opened_on']==='2026-02-01','unused account type and opening change together');
check(!(int)$f->accountSettings($id)['fints_read']&&!(int)$f->accountSettings($id)['fints_write'],'cash has no FinTS permissions');
$f->saveAccountSettings($id,2,true,'',true,false,'Bank again','offline','20','2026-01-01');
$f->createTransaction(['account'=>$id,'booked_on'=>'2026-02-01','direction'=>'income','amount'=>'5','description'=>'Synthetic received payment','counterparty'=>'Outside name'],bin2hex(random_bytes(16)));
$snapshot=MySqlFixture::snapshot($db);
foreach([['cash',null,null],['offline','21',null],['offline',null,'2026-01-02']] as [$kind,$opening,$day])denied(fn()=>$f->saveAccountSettings($id,3,true,'',true,false,'Bank again',$kind,$opening,$day),'used account protects type and opening');
denied(fn()=>$f->deleteAccount($id,'Bank again',3),'even unallocated transaction prevents deletion');
check(MySqlFixture::snapshot($db)===$snapshot,'blocked structural changes preserve transactions');
$f->saveAccountSettings($id,3,false,'',true,false,'Archived bank');check(!$f->accountSettings($id)['active']&&count($f->transactions())===1,'used account can be renamed and disabled without data loss');
$mapped=$f->createAccount('Mapped bank','offline','0','2026-01-01');$db->prepare('INSERT INTO bank_account_mappings VALUES(?,?,?,?,?,?,?,?,?)')->execute(['a','mapping','fints','PRODUCTION',str_repeat('a',64),$mapped,'Synthetic','writer',gmdate('c')]);
denied(fn()=>$f->saveAccountSettings($mapped,0,true,'',true,false,null,'cash'),'mapped account cannot become cash');
denied(fn()=>$f->deleteAccount($mapped,'Mapped bank'),'mapped account cannot be deleted');
$setting=$f->createAccount('Invoice bank','offline','0','2026-01-01');$settings->save('bank',['account_id'=>$setting],0);
denied(fn()=>$f->deleteAccount($setting,'Invoice bank'),'settings reference protects deletion');
$inventory=$f->createAccount('Inventory cash','cash','0','2026-01-01');$db->prepare("INSERT INTO inventory_items(club_id,id,code,name,kind,cash_account) VALUES('a','cashitem','SYN-1','Synthetic','reusable',?)")->execute([$inventory]);
denied(fn()=>$f->saveAccountSettings($inventory,0,true,'',true,false,null,'offline'),'inventory cash reference protects type');
$fresh=$f->createAccount('Unused account','offline','9','2026-01-01');denied(fn()=>$f->deleteAccount($fresh,'wrong'),'delete needs exact name');
denied(fn()=>$f->deleteAccount($fresh,'Unused account',99),'delete needs current version');
FinanceWorkflowActions::handle($db,'writer',['action'=>'finance-account-delete','account'=>$fresh,'version'=>'0','confirm_name'=>'Unused account']);
denied(fn()=>$f->account($fresh),'unused account actually deleted');check(count($f->transactions())===1,'unused delete preserves other transactions');
$db->exec("INSERT INTO contacts(id,club_id,kind,name,email) VALUES('member','a','person','Mara Muster','secret@example.invalid'),('contact','a','organisation','Test & Partner',''),('foreign','b','person','Foreign Person',''),('archived','a','person','Archived Person','');UPDATE contacts SET archived_at='2026-01-01' WHERE id='archived';INSERT INTO memberships(id,club_id,contact_id,member_number,status,starts_on) VALUES('m','a','member','SYN-1','aktiv','2026-01-01')");
$parties=$f->counterparties();check(count($parties)===2&&array_keys($parties[0])===['name','is_member'],'search only names in own club, no archived or private details');
denied(fn()=>(new Finance($db,'reader'))->counterparties(),'reader cannot use transaction-entry contact search');
$render=static function(string $template,string $actor,array $get,array $post=[])use($db):string{$_SESSION=['actor'=>$actor,'csrf'=>'synthetic'];$_GET=$get;$_POST=$post;$finance=new Finance($db,$actor);$documents=new \Kulturhus\Verein\Documents($db,$actor);$accountRows=$finance->accounts();$accountId=input($get,'account');$selectedAccount=$accountId!==''?$finance->account($accountId):null;$canFinance=true;$error='';$bankWorkflowError='';$fintsAvailable=true;$fintsCredentialStatus=['saved'=>true,'bank_id'=>''];$fintsDefaultBank=['name'=>'Synthetic bank'];$fintsStatus=[];if(input($get,'fints')==='1')$_SESSION['fints_target_account']=$accountId;ob_start();try{require \Kulturhus\Verein\Web\Templates::path($template);return ob_get_clean();}catch(Throwable $e){ob_end_clean();throw $e;}};
$html=$render('bank','writer',['account'=>$other]);check(str_contains($html,'Kontoeinstellungen')&&str_contains($html,'edit_account=1'),'visible edit link beside account');check(!str_contains($html,'Testkonto')&&!str_contains($html,'account-delete-panel'),'old test deletion panel removed');
$html=$render('bank','writer',['account'=>$other,'edit_account'=>'1']);check(str_contains($html,'name="opening"')&&str_contains($html,'name="kind"')&&str_contains($html,'finance-account-delete'),'unused editor has balance type and safe deletion');check(str_contains($html,'Buchhaltungskonto (SKR42)')&&!str_contains($html,'Steuerkonto dauerhaft'),'clear bookkeeping label');file_put_contents(__DIR__.'/bank-account-edit-ui.html',$html);
$html=$render('bank','writer',['account'=>$id,'edit_account'=>'1']);check(!str_contains($html,'name="opening"')&&!str_contains($html,'name="kind"')&&!str_contains($html,'value="finance-account-delete"'),'used editor protects history but allows disable');
$html=$render('finance-account-settings','reader',['account'=>$other]);check(trim($html)==='','no edit form for read-only role');
$html=$render('bank','writer',['account'=>$other,'edit_account'=>'1'],['action'=>'finance-account-settings','account'=>$other,'version'=>'7','name'=>'Draft <name>','opening'=>'bad']);check(str_contains($html,'name="version" value="7"')&&str_contains($html,'Draft &lt;name&gt;')&&str_contains($html,'value="bad"'),'failed editor preserves submitted version and escaped draft');
$html=$render('transaction-new','writer',['account'=>$other]);check(str_contains($html,'list="transaction-counterparties"')&&str_contains($html,'Mara Muster')&&str_contains($html,'Test &amp; Partner'),'contact suggestions with free text available');check(!str_contains($html,'Foreign Person')&&!str_contains($html,'secret@example.invalid')&&!str_contains($html,'Onlinebanking ist noch nicht'),'no foreign contact, email or obsolete onlinebanking warning');
$html=$render('fints-bank','writer',['account'=>$other,'fints'=>'1','edit_fints'=>'1']);check(str_contains($html,'<details open><summary>Bank, Benutzername oder PIN ändern'),'saved FinTS access editor directly expanded');
check(MySqlFixture::foreignKeyErrors($db)===[],'account edits leave references intact');
echo "$n bank account edit checks passed; synthetic MySQL and rendered UI, no bank or mail call\n";
